using Dabbler.Api.Querying;
using Dabbler.Security.Authorization;
using AcmeCoffeeOnline.Api.Services;
using AcmeCoffeeOnline.Shared.DTOs;
using Microsoft.AspNetCore.Mvc;

namespace AcmeCoffeeOnline.Api.Controllers;

/// <summary>
/// CRUD + grid-query controller for the <see cref="SupplierDto"/> aggregate.
/// Generated by the dabbler-crud-service template. The auth attributes
/// (<see cref="DabblerEndpointAuthorizeAttribute"/>) run before action method bodies, so
/// mutations are only reached after the policy check passes.
/// </summary>
[ApiController]
[Route("api/[controller]")]
public class SuppliersController : ControllerBase
{
    private readonly ISupplierService _service;

    public SuppliersController(ISupplierService service)
    {
        _service = service;
    }

    /// <summary>
    /// QBE grid query: composite filter (recursive AND/OR), multi-column sort, paging.
    /// POST (not GET) because nested filter graphs do not round-trip through query-string encoding.
    /// </summary>
    [HttpPost("query")]
    [DabblerEndpointAuthorize("QuerySupplier")]
    public async Task<ActionResult<GridQueryResponse<SupplierDto>>> QueryAsync(
        [FromBody] GridQueryRequest request,
        CancellationToken cancellationToken)
    {
        var response = await _service.QueryAsync(request, cancellationToken);
        return Ok(response);
    }

    [HttpGet("{id:int}")]
    [DabblerEndpointAuthorize("GetSupplier")]
    public async Task<ActionResult<SupplierDto>> GetByIdAsync(
        int id,
        CancellationToken cancellationToken)
    {
        var dto = await _service.GetByIdAsync(id, cancellationToken);
        return dto is null ? NotFound() : Ok(dto);
    }

    [HttpPost]
    [DabblerEndpointAuthorize("CreateSupplier")]
    public async Task<ActionResult<SupplierDto>> CreateAsync(
        [FromBody] SupplierDto dto,
        CancellationToken cancellationToken)
    {
        var created = await _service.CreateAsync(dto, cancellationToken);
        return Ok(created);
    }

    [HttpPut("{id:int}")]
    [DabblerEndpointAuthorize("UpdateSupplier")]
    public async Task<ActionResult<SupplierDto>> UpdateAsync(
        int id,
        [FromBody] SupplierDto dto,
        CancellationToken cancellationToken)
    {
        var updated = await _service.UpdateAsync(id, dto, cancellationToken);
        return updated is null ? NotFound() : Ok(updated);
    }

    [HttpDelete("{id:int}")]
    [DabblerEndpointAuthorize("DeleteSupplier")]
    public async Task<IActionResult> DeleteAsync(
        int id,
        CancellationToken cancellationToken)
    {
        return await _service.DeleteAsync(id, cancellationToken) ? NoContent() : NotFound();
    }
}
